import workcell
def probe_from(x,y,start_z,step=-1,thr=0.5,max_steps=20):
    workcell.call("arm","move",str(x),str(y),"150")
    workcell.call("arm","move",str(x),str(y),str(start_z))
    print(f"--- XY {x},{y} from {start_z} ---")
    for i in range(max_steps):
        r=workcell.call("arm","step",str(step))
        z=r.data.get("z_mm"); fz=r.data.get("fz_N")
        print(f"  z={z:.3f} fz={fz:.3f}")
        if fz>thr:
            r2=workcell.call("ft","read")
            print(f"  CONTACT {r2.text}")
            break
        if z<20:
            print("  reached low, no contact")
            break
    for j in range(10):
        r=workcell.call("arm","step","5")
        if r.data.get("z_mm",0)>130:
            break
    workcell.call("arm","move",str(x),str(y),"150")

# map X across stand at start 70 (just above yellow)
for x in [570,580,590,600,610,550,540,530,520]:
    probe_from(x,-10,70,-1,thr=0.5,max_steps=15)
