from PIL import Image
files=[
 ("/home/robot/captures/side_008.jpg",7.285),
 ("/home/robot/captures/side_009.jpg",12.392),
 ("/home/robot/captures/side_010.jpg",15.049),
 ("/home/robot/captures/side_011.jpg",20.674),
 ("/home/robot/captures/side_012.jpg",26.661),
 ("/home/robot/captures/side_013.jpg",33.079),
 ("/home/robot/captures/side_014.jpg",36.391),
 ("/home/robot/captures/side_015.jpg",43.495),
]
def profile(im,x0,x1,y0,y1):
    px=im.load()
    return [sum(px[x,y] for x in range(x0,x1+1))/(x1-x0+1) for y in range(y0,y1)]
Y0=195
for f,F in files:
    im=Image.open(f).convert("L")
    p=profile(im,300,304,Y0,260)
    mins_idx=[]
    for idx in range(2,len(p)-2):
        if p[idx]==min(p[idx-2:idx+3]) and p[idx]<60:
            if not mins_idx or idx-mins_idx[-1]>=3:
                mins_idx.append(idx)
            else:
                if p[idx]<p[mins_idx[-1]]:
                    mins_idx[-1]=idx
    refined=[]
    for idx in mins_idx:
        a=p[idx-1]; b=p[idx]; c=p[idx+1]
        denom=(a-2*b+c)
        if denom!=0:
            off=0.5*(a-c)/denom
            if -1<off<1:
                y_ref=Y0+idx+off
            else:
                y_ref=float(Y0+idx)
        else:
            y_ref=float(Y0+idx)
        refined.append(y_ref)
    print(f"{f[-12:]} F={F} N={len(refined)} Y={[f'{y:.2f}' for y in refined]}")
